def parse_nested_parens(paren_string: str) -> List[int]:
    def calculate_depth(group):
        stack = []
        max_depth = 0
        current_depth = 0

        for char in group:
            if char == '(':
                stack.append(char)
                current_depth = len(stack)
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                stack.pop()

        return max_depth

    groups = paren_string.split()
    result = [calculate_depth(group) for group in groups]

    return result
